class PushBoxGame:
    WALL = "#"
    PLAYER = "O"
    TARGET = "G"
    BOX = "X"

    def __init__(self, grid_map):
        self.map = grid_map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False

        self.init_game()

    def init_game(self):
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                self.process_cell(row, col)

    def process_cell(self, row, col):
        cell = self.map[row][col]
        if cell == self.PLAYER:
            self.player_row = row
            self.player_col = col
        elif cell == self.TARGET:
            self.targets.append((row, col))
            self.target_count += 1
        elif cell == self.BOX:
            self.boxes.append((row, col))

    def count_boxes_on_targets(self):
        return sum(1 for box in self.boxes if box in self.targets)

    def check_win(self):
        if self.count_boxes_on_targets() == self.target_count:
            self.is_game_over = True
        return self.is_game_over

    def get_new_position(self, direction):
        new_player_row = self.player_row
        new_player_col = self.player_col

        if direction == "w":
            new_player_row -= 1
        elif direction == "s":
            new_player_row += 1
        elif direction == "a":
            new_player_col -= 1
        elif direction == "d":
            new_player_col += 1

        return new_player_row, new_player_col

    def is_wall(self, row, col):
        return self.map[row][col] == self.WALL

    def move_box(self, direction):
        new_player_row, new_player_col = self.get_new_position(direction)
        new_box_row = new_player_row + (new_player_row - self.player_row)
        new_box_col = new_player_col + (new_player_col - self.player_col)

        if not self.is_wall(new_box_row, new_box_col):
            self.boxes.remove((new_player_row, new_player_col))
            self.boxes.append((new_box_row, new_box_col))
            self.move_player_to(new_player_row, new_player_col)

    def move_player_to(self, row, col):
        self.player_row = row
        self.player_col = col

    def can_move_to(self, row, col):
        return not self.is_wall(row, col)

    def move(self, direction):
        new_player_row, new_player_col = self.get_new_position(direction)

        if not self.can_move_to(new_player_row, new_player_col):
            return self.check_win()

        if (new_player_row, new_player_col) in self.boxes:
            self.move_box(direction)
        else:
            self.move_player_to(new_player_row, new_player_col)

        return self.check_win()
